/* Generated by scripts/build-tool-docs.mjs --write; edit the changelog editor modules. */
(function () {
  "use strict";
  function createChangelogLibrary() {

  const REPO = 'Moyf/moys-asr-workflow';
  const VERSION_RE = /^v(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$/;
  const BASE_MARK_RE = /^<!-- release-base: ([^\s]+) -->$/;
  const IMAGE_SUFFIX_RE = /\.(png|jpe?g|gif|webp|svg|avif)$/i;
  const HEAD_SCHEME_RE = /^[a-zA-Z][a-zA-Z0-9+.-]*:/;

  function escapeReg(text) {
    return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  }

  function parseTag(version) {
    const tag = version.startsWith('v') ? version : 'v' + version;
    const match = VERSION_RE.exec(tag);
    if (!match) return null;
    if (match[4]) {
      for (const part of match[4].split('.')) {
        if (/^\d+$/.test(part) && part.length > 1 && part[0] === '0') return null;
      }
    }
    return match;
  }

  function isStable(version) {
    const match = parseTag(version);
    return Boolean(match) && !match[4];
  }

  /** Python re 的 (?ms)^## \[name\][^\n]*\n.*?(?=^## \[|\Z) 等价实现；要求恰好一处。 */
  function extractSection(changelog, version) {
    const text = String(changelog).replace(/\r\n/g, '\n');
    const pattern = new RegExp(
      '^## \\[' + escapeReg(version) + '\\][^\\n]*\\n[\\s\\S]*?(?=^## \\[|$(?![\\s\\S]))', 'gm');
    const matches = text.match(pattern);
    if (!matches || matches.length === 0) throw new Error(`CHANGELOG.md does not contain a release section for ${version}.`);
    if (matches.length !== 1) throw new Error(`duplicate CHANGELOG.md release section for ${version}.`);
    return matches[0].trim();
  }

  function normPosixPath(path) {
    if (path === '') return '.';
    const absolute = path.startsWith('/');
    const out = [];
    for (const part of path.split('/')) {
      if (part === '' || part === '.') continue;
      if (part === '..') {
        if (out.length && out[out.length - 1] !== '..') out.pop();
        else if (!absolute) out.push('..');
      } else out.push(part);
    }
    let joined = out.join('/');
    if (absolute) joined = '/' + joined;
    return joined === '' ? (absolute ? '/' : '.') : joined;
  }

  function quotePath(path) {
    return path.split('/').map(encodeURIComponent).join('/');
  }

  /** pinned_link 的等价实现；target 为仓库相对路径时固定到 tag。 */
  function pinnedLink(target, tag, image) {
    if (HEAD_SCHEME_RE.test(target) || target.startsWith('//') || target.startsWith('#')) return target;
    let rest = target, query = '', fragment = '';
    const hashIdx = rest.indexOf('#');
    if (hashIdx >= 0) { fragment = rest.slice(hashIdx + 1); rest = rest.slice(0, hashIdx); }
    const qIdx = rest.indexOf('?');
    if (qIdx >= 0) { query = rest.slice(qIdx + 1); rest = rest.slice(0, qIdx); }
    let decoded;
    try { decoded = decodeURIComponent(rest); } catch { decoded = rest; }
    const path = normPosixPath(decoded.replace(/^\/+/, ''));
    if (path === '..' || path.startsWith('../') || path.includes('\\')) {
      throw new Error(`link outside the repository: ${target}`);
    }
    const isImage = image || IMAGE_SUFFIX_RE.test(path);
    const base = isImage
      ? `https://raw.githubusercontent.com/${REPO}/${tag}/`
      : `https://github.com/${REPO}/blob/${tag}/`;
    return base + quotePath(path) + (query ? '?' + query : '') + (fragment ? '#' + fragment : '');
  }

  /** pin_repo_links 等价实现：代码围栏与行内代码保持原样。 */
  function pinRepoLinks(markdown, tag) {
    const lines = [];
    let fence = null;
    for (const line of markdown.split('\n')) {
      const marker = line.match(/^ {0,3}(`{3,}|~{3,})(.*)$/);
      if (fence) {
        if (marker && marker[1][0] === fence[0] && marker[1].length >= fence.length && !marker[2].trim()) fence = null;
        lines.push(line);
        continue;
      }
      if (marker) { fence = marker[1]; lines.push(line); continue; }
      const visible = line.replace(/(`+)[\s\S]*?\1/g, (m) => ' '.repeat(m.length));
      const replacements = [];
      let cursor = 0;
      for (;;) {
        const start = visible.indexOf('](', cursor);
        if (start < 0) break;
        let begin = start + 2;
        let end;
        if (begin < line.length && line[begin] === '<') {
          end = line.indexOf('>', begin + 1);
          if (end < 0) break;
          begin += 1;
          cursor = end + 1;
        } else {
          let depth = 1;
          end = begin;
          while (end < line.length) {
            const char = line[end];
            if (char === '\\') { end += 2; continue; }
            if (char === '(') depth += 1;
            else if (char === ')') { depth -= 1; if (depth === 0) break; }
            else if (/\s/.test(char) && depth === 1) break;
            end += 1;
          }
          cursor = Math.max(end + 1, begin + 1);
        }
        const image = /!\[[^\]]*$/.test(visible.slice(0, start));
        replacements.push([begin, end, pinnedLink(line.slice(begin, end), tag, image)]);
      }
      const definition = visible.match(/^ {0,3}\[[^\]]+\]:\s*(?:<([^>]+)>|(\S+))/d);
      if (definition) {
        const groupIndex = definition[1] !== undefined ? 1 : 2;
        const dIndices = definition.indices;
        if (dIndices && dIndices[groupIndex]) {
          replacements.push([...dIndices[groupIndex], pinnedLink(definition[groupIndex], tag)]);
        }
      }
      for (const match of visible.matchAll(/\b(src|href)\s*=\s*["']([^"']+)["']/gid)) {
        replacements.push([match.indices[2][0], match.indices[2][1],
          pinnedLink(match[2], tag, match[1].toLowerCase() === 'src')]);
      }
      replacements.sort((a, b) => b[0] - a[0]);
      let result = line;
      for (const [begin, end, target] of replacements) {
        result = result.slice(0, begin) + target + result.slice(end);
      }
      lines.push(result);
    }
    return lines.join('\n');
  }

  async function sha256Hex(text) {
    const bytes = new TextEncoder().encode(text);
    const digest = await crypto.subtle.digest('SHA-256', bytes);
    return Array.from(new Uint8Array(digest), (b) => b.toString(16).padStart(2, '0')).join('');
  }

  const DOC_PREFIX = '<!-- maw-release ';

  /** build_release_document 等价实现；仅接受正式版。返回完整文档文本。 */
  async function buildArchive(changelog, version) {
    const parsed = parseTag(version);
    if (!parsed) throw new Error(`invalid release tag: v${version}`);
    if (parsed[4]) throw new Error(`v${version}: only stable versions can be archived in docs/releases`);
    const section = extractSection(changelog, version);
    const firstLine = section.split('\n')[0];
    const heading = firstLine.match(/^## \[[^\]]+\] - (\d{4}-\d{2}-\d{2})$/);
    if (!heading) throw new Error(`v${version}: release heading needs an ISO date: ## [${version}] - YYYY-MM-DD`);
    const iso = heading[1];
    if (Number.isNaN(Date.parse(iso + 'T00:00:00Z'))) throw new Error(`v${version}: invalid date ${iso}`);

    const sectionLines = section.split('\n');
    const bases = sectionLines.map((line) => {
      const found = BASE_MARK_RE.exec(line);
      return found ? found[1] : null;
    }).filter(Boolean);
    const leftoverBase = sectionLines.some((line) => line.includes('<!-- release-base:') && !BASE_MARK_RE.test(line));
    if (bases.length > 1 || leftoverBase) {
      throw new Error(`v${version}: expected at most one <!-- release-base: X.Y.0 --> marker`);
    }
    const base = bases[0] || null;
    if (base) {
      const baseParsed = parseTag(base);
      if (!baseParsed || baseParsed[4] || baseParsed[3] !== '0'
        || baseParsed[1] !== parsed[1] || baseParsed[2] !== parsed[2]
        || Number(parsed[3]) === 0) {
        throw new Error(`v${version}: base must be the stable X.Y.0 of the same patch series`);
      }
    }
    const sourceSha256 = await sha256Hex(section);
    // 与 Python json.dumps(..., sort_keys=True) 完全一致：键名字典序、", " / ": " 分隔、非 ASCII 不转义。
    const fields = [
      ['base', base], ['channel', 'stable'], ['date', iso],
      ['schema', 'maw.release.v1'], ['source_sha256', sourceSha256], ['version', version],
    ];
    const metadataJson = `{${fields.map(([key, value]) => `${JSON.stringify(key)}: ${JSON.stringify(value)}`).join(', ')}}`;
    let body = sectionLines.filter((line) => !BASE_MARK_RE.test(line)).join('\n');
    body = body.replace(/\n{3,}/g, '\n\n').trim();
    return `${DOC_PREFIX}${metadataJson} -->\n\n${pinRepoLinks(body, 'v' + version)}\n`;
  }

  function documentParts(documentText) {
    const sep = '\n\n';
    const sepIdx = documentText.indexOf(sep);
    const header = sepIdx >= 0 ? documentText.slice(0, sepIdx) : documentText;
    const body = sepIdx >= 0 ? documentText.slice(sepIdx + sep.length) : '';
    if (!header.startsWith(DOC_PREFIX) || !header.endsWith(' -->')) {
      throw new Error('invalid release document header');
    }
    return { metadata: JSON.parse(header.slice(DOC_PREFIX.length, -4)), body: body.trim() };
  }

  // ---------- CHANGELOG 结构化解析 / 序列化（往返无损） ----------

  function splitSections(changelog) {
    const text = String(changelog).replace(/\r\n/g, '\n');
    const headingRe = /^## \[([^\]]+)\]([^\n]*)$/gm;
    const found = [];
    for (const match of text.matchAll(headingRe)) {
      found.push({ name: match[1].trim(), suffix: match[2], index: match.index, end: match.index + match[0].length });
    }
    const preamble = found.length ? text.slice(0, found[0].index) : text;
    const sections = [];
    found.forEach((item, i) => {
      const rawStart = item.index;
      const rawEnd = i + 1 < found.length ? found[i + 1].index : text.length;
      const dateMatch = /^\s*-\s*(\d{4}-\d{2}-\d{2})\s*$/.exec(item.suffix);
      sections.push({
        name: item.name,
        date: dateMatch ? dateMatch[1] : null,
        heading: `## [${item.name}]${item.suffix}`,
        rawText: text.slice(rawStart, rawEnd),
      });
    });
    return { preamble, sections };
  }

  /** 把一个版本小节解析成卡片。卡片 lines 为正文行；blanksBefore 保留原有空行数。
   *  条目卡片的 images 为统一图片列表：{kind:'existing', alt, path}（已在 CL 中）或 {kind:'new', id}（粘贴待写盘）。 */
  function parseSection(section) {
    const content = section.rawText.split('\n').slice(1); // 去掉标题行
    if (content.length && content[content.length - 1] === '') content.pop(); // 去掉结尾换行产生的空尾巴
    const cards = [];
    let blanks = 0;
    const pushCard = (card) => {
      card.blanksBefore = blanks;
      blanks = 0;
      cards.push(card);
    };
    for (const line of content) {
      if (line.trim() === '') { blanks += 1; continue; }
      if (line.startsWith('- ')) {
        pushCard({ kind: 'entry', lines: [line], images: [], original: line });
      } else if (/^!\[/.test(line) && blanks === 0 && cards.length && cards[cards.length - 1].kind === 'entry') {
        const altMatch = /^!\[([^\]]*)\]\(([^)\s]+)\)\s*$/.exec(line);
        if (altMatch) {
          cards[cards.length - 1].images.push({ kind: 'existing', alt: altMatch[1], path: altMatch[2] });
        } else {
          pushCard({ kind: 'text', lines: [line], original: line });
        }
      } else if (/^#+ /.test(line)) {
        pushCard({ kind: 'heading', lines: [line], original: line });
      } else {
        pushCard({ kind: 'text', lines: [line], original: line });
      }
    }
    return { cards, trailingBlanks: blanks };
  }

  function serializeSection(section, parsed) {
    const lines = [section.heading];
    for (const card of parsed.cards) {
      for (let i = 0; i < card.blanksBefore; i += 1) lines.push('');
      if (card.kind === 'entry') lines.push(...entryCardToLines(card));
      else lines.push(...card.lines);
    }
    for (let i = 0; i < parsed.trailingBlanks; i += 1) lines.push('');
    return lines.join('\n') + '\n';
  }

  /** 新条目插入后的行：条目行 + 已确认图片行（新图片在写盘前不进 CL）。 */
  function entryCardToLines(card) {
    const lines = [card.lines[0]];
    for (const img of card.images || []) {
      if (img.kind === 'existing') lines.push(`![${img.alt}](${img.path})`);
    }
    return lines;
  }

  // ---------- 轻量逐词 diff（条目为单行，规模很小） ----------

  function tokenize(text) {
    return text.split(/(\s+)/).filter((t) => t !== '');
  }

  function wordDiff(oldText, newText) {
    if (oldText === newText) return [{ type: 'same', text: newText }];
    const a = tokenize(oldText);
    const b = tokenize(newText);
    if (a.length * b.length > 400000) {
      return [{ type: 'del', text: oldText }, { type: 'ins', text: newText }];
    }
    const n = a.length, m = b.length;
    const dp = Array.from({ length: n + 1 }, () => new Uint32Array(m + 1));
    for (let i = n - 1; i >= 0; i -= 1) {
      for (let j = m - 1; j >= 0; j -= 1) {
        dp[i][j] = a[i] === b[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
      }
    }
    const ops = [];
    let i = 0, j = 0;
    const flush = (type, text) => {
      if (!text) return;
      const last = ops[ops.length - 1];
      if (last && last.type === type) last.text += text;
      else ops.push({ type, text });
    };
    while (i < n && j < m) {
      if (a[i] === b[j]) { flush('same', a[i]); i += 1; j += 1; }
      else if (dp[i + 1][j] >= dp[i][j + 1]) { flush('del', a[i]); i += 1; }
      else { flush('ins', b[j]); j += 1; }
    }
    while (i < n) { flush('del', a[i]); i += 1; }
    while (j < m) { flush('ins', b[j]); j += 1; }
    return ops;
  }

  return {
    REPO, VERSION_RE, parseTag, isStable, extractSection, pinnedLink, pinRepoLinks,
    sha256Hex, buildArchive, documentParts, splitSections, parseSection,
    serializeSection, entryCardToLines, wordDiff,
  };
}
  function mountChangelogEditor(L) {
  const $ = (sel) => document.querySelector(sel);

  // ---------- 页面状态 ----------
  const S = {
    repo: null,            // 根目录句柄（降级模式为 null）
    repoName: '',
    clText: '',            // 当前编辑中的全文
    baseText: '',          // 载入时的磁盘文本（冲突检测基线）
    baseHash: '',
    sections: [],          // splitSections 结果
    parsed: new Map(),     // name -> { cards, trailingBlanks }
    selected: null,        // 当前版本名
    selectedCard: null,    // 粘贴目标卡片（对象引用，跨重排/增删稳定；换小节时重置）
    images: new Map(),     // id -> {id, blob, mime, size, alt, filename, version, cardKey}
    archiveStatus: new Map(), // version -> fresh|stale|missing|none
    tab: 'split',
    readOnly: false,
    unlocked: new Set(),     // 已确认可编辑的历史测试版
  };
  const LS_STATE = () => `cl-editor:state:${S.baseHash}`;
  const LS_REFS = () => `cl-editor:refs:${S.baseHash}`;
  const LS_IMGS = () => `cl-editor:imgs:${S.baseHash}`;

  // ---------- 基础 UI ----------
  let toastTimer = null;
  function toast(msg, isErr = false) {
    const el = $('#toast');
    el.textContent = msg;
    el.className = isErr ? 'err' : '';
    el.style.display = 'block';
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => { el.style.display = 'none'; }, isErr ? 6000 : 2600);
  }
  let modalReturnFocus = null;
  let modalCancel = null;
  let imageOperationGeneration = 0;
  let finishInProgress = false;
  let backgroundLockState = null;
  function setModalBackgroundLocked(locked) {
    if (locked === Boolean(backgroundLockState)) return;
    if (locked) {
      modalReturnFocus = document.activeElement;
      backgroundLockState = {
        backgrounds: ['layout', 'topbar', 'restore-banner', 'lock-banner'].map((id) => {
          const node = document.getElementById(id);
          return { node, inert: node.inert };
        }),
        roots: [document.documentElement, document.body].map((node) => ({
          node,
          overflow: ['overflow-x', 'overflow-y'].map((property) => ({
            property, value: node.style.getPropertyValue(property), priority: node.style.getPropertyPriority(property),
          })),
        })),
      };
      for (const { node } of backgroundLockState.backgrounds) node.inert = true;
      for (const { node } of backgroundLockState.roots) node.style.overflow = 'hidden';
    } else {
      const previous = backgroundLockState;
      backgroundLockState = null;
      for (const { node, inert } of previous.backgrounds) node.inert = inert;
      for (const { node, overflow } of previous.roots) {
        node.style.removeProperty('overflow');
        for (const { property, value, priority } of overflow) node.style.setProperty(property, value, priority);
      }
      const target = modalReturnFocus;
      modalReturnFocus = null;
      if (target?.isConnected && !target.closest('[inert]') && !target.disabled && target.getClientRects().length) {
        target.focus({ preventScroll: true });
      }
    }
  }
  function refreshBackgroundLock() {
    setModalBackgroundLocked(finishInProgress || $('#mask').classList.contains('show'));
  }
  function modal(html, onCancel = null) {
    imageOperationGeneration += 1;
    $('#modal').innerHTML = html; $('#mask').classList.add('show');
    modalCancel = onCancel;
    refreshBackgroundLock();
    const focus = $('#modal').querySelector('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled)');
    (focus || $('#modal')).focus();
  }
  function closeModal(cancelled = false) {
    const onCancel = modalCancel; modalCancel = null;
    $('#mask').classList.remove('show');
    refreshBackgroundLock();
    if(cancelled && onCancel)onCancel();
  }
  $('#mask').addEventListener('keydown',event=>{
    if(event.key==='Escape') {event.preventDefault();closeModal(true);return;}
    if(event.key!=='Tab')return;
    const nodes=[...$('#modal').querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]')].filter(node=>node.getClientRects().length);
    if(!nodes.length){event.preventDefault();$('#modal').focus();return;}
    const first=nodes[0],last=nodes[nodes.length-1];
    if(event.shiftKey&&(document.activeElement===first||document.activeElement===$('#modal'))){event.preventDefault();last.focus();}
    else if(!event.shiftKey&&(document.activeElement===last||document.activeElement===$('#modal'))){event.preventDefault();first.focus();}
  });
  $('#mask').addEventListener('click', (e) => { if (e.target === $('#mask')) closeModal(true); });

  function markDirty() {
    $('#dirty-dot').style.display = 'inline';
    scheduleAutosave();
  }
  function markClean() { $('#dirty-dot').style.display = 'none'; }

  // ---------- 载入 ----------
  async function loadClText(text, label) {
    S.clText = text.replace(/\r\n/g, '\n');
    S.baseText = S.clText;
    S.baseHash = await L.sha256Hex(S.baseText);
    S.repoName = label;
    reparse();
    $('#repo-chip').textContent = label;
    $('#repo-chip').className = S.repo ? 'ok' : '';
    $('#btn-finish').disabled = false;
    const restore = localStorage.getItem(LS_STATE());
    if (restore) {
      const state = JSON.parse(restore);
      $('#restore-text').textContent = `检测到 ${new Date(state.savedAt).toLocaleString()} 的未完成编辑（含 ${state.imageCount || 0} 张图片）`;
      $('#restore-banner').style.display = 'flex';
      $('#btn-restore').onclick = () => doRestore(state);
      $('#btn-discard').onclick = () => { localStorage.removeItem(LS_STATE()); localStorage.removeItem(LS_REFS()); $('#restore-banner').style.display = 'none'; };
    } else {
      // 换了载入内容（hash 变化）后旧 banner 的闭包指向旧状态，必须隐藏，
      // 否则「恢复」会把旧文本写进新 hash 的存档键造成污染
      $('#restore-banner').style.display = 'none';
    }
    selectSection(S.selected || firstEditableSection());
  }

  function reparse() {
    const { preamble, sections } = L.splitSections(S.clText);
    S.sections = sections;
    S.parsed.clear();
    for (const s of sections) S.parsed.set(s.name, L.parseSection(s));
  }

  function firstEditableSection() {
    const unrel = S.sections.find((s) => s.name === '未发布');
    return (unrel || S.sections[0])?.name || null;
  }

  /** 连接仓库根目录：校验 CHANGELOG.md、加载并刷新界面。
   *  目录无效（移动/删除）时抛错，由调用方按场景提示。 */
  async function connectRepo(root) {
    const clFile = await root.getFileHandle('CHANGELOG.md');
    S.repo = root; S.readOnly = false;
    const text = await (await clFile.getFile()).text();
    await loadClText(text, `📦 ${root.name}（读写）`);
    await refreshArchiveStatus();
    renderSidebar();
    hideReconnectUi();
    toast('仓库目录已连接，可以读取与写回');
  }

  async function openRepo() {
    let root;
    try {
      root = await window.showDirectoryPicker({ id: 'maw-cl-editor', mode: 'readwrite' });
    } catch { return; }
    try {
      await connectRepo(root);
      await idbSaveHandle(root).catch(() => {}); // 持久化失败不影响本次连接
    } catch {
      toast('所选目录没有 CHANGELOG.md，请选择仓库根目录', true);
    }
  }

  /** 用持久化的句柄重连：权限仍在则免提示直连，否则浏览器弹一次授权确认；
   *  句柄失效（目录被移动/删除）时清理记忆并降级为手动选择。 */
  async function tryReconnect(handle) {
    let perm = 'prompt';
    try { perm = await handle.queryPermission({ mode: 'readwrite' }); } catch { /* 非法句柄 */ }
    if (perm !== 'granted') {
      try { perm = await handle.requestPermission({ mode: 'readwrite' }); } catch { perm = 'denied'; }
    }
    if (perm !== 'granted') return false;
    // 授权等待期间用户可能已手动打开仓库 / 载入文件，不得覆盖其选择
    if (S.repo || S.selected) return false;
    try {
      await connectRepo(handle);
      await idbSaveHandle(handle).catch(() => {});
      return true;
    } catch {
      await idbClearHandle().catch(() => {});
      hideReconnectUi();
      toast('上次连接的目录已不可用，请重新手动选择', true);
      return false;
    }
  }

  function showReconnectUi(name) {
    $('#reconnect-name').textContent = name;
    $('#btn-reconnect').hidden = false;
    $('#btn-forget-repo').hidden = false;
  }

  function hideReconnectUi() {
    $('#btn-reconnect').hidden = true;
    $('#btn-forget-repo').hidden = true;
  }

  /** 启动时尝试静默重连：权限已被浏览器记住（granted）就直接连；
   *  需要授权则亮出「重连」按钮，等用户点击（requestPermission 需要用户手势）。 */
  async function bootReconnect() {
    let handle;
    try { handle = await idbLoadHandle(); } catch { return; }
    if (!handle || S.repo || S.selected) return;
    let granted = false;
    try { granted = (await handle.queryPermission({ mode: 'readwrite' })) === 'granted'; } catch { return; }
    if (granted) {
      if (await tryReconnect(handle)) toast('已自动重连上次的仓库目录', false);
      return;
    }
    showReconnectUi(handle.name);
  }

  async function loadFileFallback() {
    $('#file-input').onchange = async () => {
      const file = $('#file-input').files[0];
      if (!file) return;
      S.repo = null; S.readOnly = true;
      hideReconnectUi();
      await loadClText(await file.text(), `📄 ${file.name}（只读降级）`);
      renderSidebar();
      toast('已按只读模式加载；完成编辑将改为下载文件', false);
    };
    $('#file-input').click();
  }

  // ---------- 侧栏 ----------
  function sectionBadge(s) {
    if (s.name === '未发布') return '';
    return L.isStable(s.name) ? '<span class="badge stable">正式</span>' : '<span class="badge pre">测试</span>';
  }

  function renderSidebar() {
    const list = $('#version-list');
    list.innerHTML = '';
    const dirty = new Set(dirtyVersions().map((s) => s.name));
    for (const s of S.sections) {
      const div = document.createElement('div');
      div.className = 'version-item' + (s.name === S.selected ? ' active' : '');
      const dot = L.isStable(s.name)
        ? `<span class="arch-dot ${S.archiveStatus.get(s.name) || ''}" title="归档状态"></span>` : '<span class="arch-dot" style="visibility:hidden"></span>';
      const pending = dirty.has(s.name) ? '<span class="pending-dot" title="有未完成的修改"></span>' : '';
      div.innerHTML = `${dot}<span class="name">${escapeHtml(s.name)}</span>${pending}${sectionBadge(s)}<span class="date">${s.date || ''}</span>`;
      div.onclick = () => selectSection(s.name);
      list.appendChild(div);
    }
    renderArchiveBox();
  }

  function renderArchiveBox() {
    const box = $('#archive-list');
    box.innerHTML = '';
    const stable = S.sections.filter((s) => L.isStable(s.name));
    for (const s of stable) {
      const status = S.archiveStatus.get(s.name);
      const row = document.createElement('label');
      row.className = 'arch-row';
      const statusText = { fresh: '一致', stale: '需重生成', missing: '缺失' }[status] || '—';
      row.innerHTML = `<input type="checkbox" data-arch="${escapeAttr(s.name)}" ${status !== 'fresh' ? 'checked' : ''}>
        <span>${escapeHtml(s.name)}</span><span class="status ${status || ''}">${statusText}</span>`;
      box.appendChild(row);
    }
    if (!stable.length) box.innerHTML = '<p class="hint">没有正式版本。</p>';
    $('#btn-generate-archives').disabled = !S.repo;
  }

  // ---------- 版本面板 ----------
  function selectSection(name) {
    // 外部编辑可能删掉当前小节（刷新重载后）：回落到第一个可选小节，避免渲染层炸掉
    if (!S.parsed.has(name)) name = firstEditableSection();
    // 小节切换后旧选中的卡片对象不属于新小节，重置粘贴目标
    if (S.selected !== name) S.selectedCard = null;
    S.selected = name;
    // 不重置 S.tab：切换版本保持当前视图（默认分屏），active 按钮跟随实际 tab
    const section = S.sections.find((s) => s.name === name);
    $('#vh-name').textContent = name;
    const dateInput = $('#vh-date');
    dateInput.value = section?.date || '';
    dateInput.style.display = section?.date || L.isStable(name) ? '' : 'none';
    $('#auto-arch-label').style.display = section && L.isStable(name) ? '' : 'none';
    renderLockBanner();
    document.querySelectorAll('#tabs button').forEach((b) => b.classList.toggle('active', b.dataset.tab === S.tab));
    renderSidebar();
    renderPane();
  }

  function isHistorical(section) {
    return section && section.name !== '未发布' && !L.isStable(section.name);
  }

  function renderLockBanner() {
    const section = S.sections.find((s) => s.name === S.selected);
    const banner = $('#lock-banner');
    if (!isHistorical(section)) { banner.classList.remove('show'); return; }
    const key = `${S.baseHash}:${section.name}`;
    if (sessionStorage.getItem(`cl-editor:ack:${key}`)) { banner.classList.remove('show'); return; }
    banner.classList.add('show');
    banner.innerHTML = `<span>⚠ 「${escapeHtml(section.name)}」是已发布的测试版小节，按惯例不再改动。确认要编辑吗？</span>
      <span style="flex:1"></span>
      <button id="btn-unlock" class="primary">仍要编辑</button>`;
    banner.querySelector('#btn-unlock').onclick = () => {
      sessionStorage.setItem(`cl-editor:ack:${key}`, '1');
      banner.classList.remove('show');
      renderPane();
    };
  }

  function renderPane() {
    const pane = $('#pane');
    pane.innerHTML = '';
    if (!S.selected) { pane.innerHTML = '<p class="hint">先用「打开仓库目录」或「仅加载 CL 文件」载入 CHANGELOG。</p>'; return; }
    if (S.tab === 'edit') renderEditPane(pane);
    else if (S.tab === 'preview') renderPreviewPane(pane);
    else if (S.tab === 'reference') renderReferencePane(pane);
    else if (S.tab === 'split') renderSplitPane(pane);
  }

  /** 历史测试版在确认前锁定编辑。 */
  function editLocked() {
    const section = S.sections.find((s) => s.name === S.selected);
    if (!isHistorical(section)) return false;
    return !sessionStorage.getItem(`cl-editor:ack:${S.baseHash}:${section.name}`);
  }

  function renderSplitPane(pane) {
    const wrap = document.createElement('div');
    wrap.id = 'split-wrap';
    wrap.className = 'show';
    const editSide = document.createElement('div');
    editSide.className = 'split-edit';
    const previewSide = document.createElement('div');
    previewSide.className = 'split-preview';
    wrap.appendChild(editSide);
    wrap.appendChild(previewSide);
    pane.appendChild(wrap);
    renderEditPane(editSide);
    renderPreviewInto(previewSide);
    if (editLocked()) wrap.querySelector('.split-edit').classList.add('locked');
  }

  let splitRefreshTimer = null;
  function scheduleSplitPreview() {
    if (S.tab !== 'split') return;
    clearTimeout(splitRefreshTimer);
    splitRefreshTimer = setTimeout(() => {
      const side = document.querySelector('#split-wrap > .split-preview');
      if (side) { side.innerHTML = ''; renderPreviewInto(side); }
    }, 400);
  }

  function cardControls(card, idx) {
    const changed = card.original != null && card.original !== card.lines.join('\n');
    const tags = [
      `<span class="tag">${card.kind === 'entry' ? '条目' : card.kind === 'heading' ? '小节' : '文本'}</span>`,
      card.original == null ? '<span class="new-tag">新增</span>' : '',
      changed ? '<span class="changed-tag">已修改</span>' : '',
    ].join('');
    return `
      <div class="card-head">
        <span class="drag-handle" title="拖拽调整顺序">⠿</span>${tags}<span class="spacer"></span>
        <button data-act="diff" title="与原文对比">对比</button>
        <button data-act="reset" title="恢复原文">还原</button>
        ${card.kind === 'entry' ? '<button data-act="img" title="添加图片文件">📎</button>' : ''}
        <button data-act="del" title="删除此条">✕</button>
      </div>`;
  }

  function renderEditPane(pane) {
    const parsed = S.parsed.get(S.selected);
    const wrap = document.createElement('div');
    wrap.id = 'cards';
    parsed.cards.forEach((card, idx) => wrap.appendChild(renderCard(card, idx)));
    if (!parsed.cards.length) {
      wrap.innerHTML = '<p class="hint">此版本暂无内容。用下方按钮添加第一个条目。</p>';
    }
    pane.appendChild(wrap);
    if (editLocked()) wrap.classList.add('locked');
    const addRow = document.createElement('div');
    addRow.className = 'add-row';
    addRow.innerHTML = '<button id="add-entry">＋ 添加条目</button><button id="add-heading" class="ghost">＋ 添加小节标题</button>';
    addRow.querySelector('#add-entry').onclick = () => addCard('entry', parsed.cards.length);
    addRow.querySelector('#add-heading').onclick = () => addCard('heading', parsed.cards.length);
    pane.appendChild(addRow);
    pane.querySelectorAll('textarea').forEach(fitTextarea);
    pane.querySelectorAll('.card').forEach((el) => {
      if (parsed.cards[Number(el.dataset.cardId)] === S.selectedCard) el.classList.add('selected');
    });
  }

  function renderCard(card, idx) {
    const el = document.createElement('div');
    const cardId = idx;
    el.className = `card kind-${card.kind}`;
    el.dataset.cardId = String(cardId);
    el.dataset.idx = String(idx);
    const isEntry = card.kind === 'entry';
    const body = isEntry
      ? `<textarea data-field="line" rows="2">${escapeHtml(card.lines[0] || '')}</textarea>`
      : `<textarea data-field="line" rows="1">${escapeHtml(card.lines[0] || '')}</textarea>`;
    el.innerHTML = cardControls(card, idx) + body +
      (isEntry ? `<div class="img-strip" data-strip></div>` : '') +
      `<div class="diff-view" data-diff style="display:none"></div>`;
    const ta = el.querySelector('textarea');
    ta.addEventListener('input', () => {
      card.lines[0] = ta.value;
      fitTextarea(ta);
      markDirty();
      refreshCardTags(el, card);
      scheduleSplitPreview();
    });
    ta.addEventListener('focus', () => selectCard(card));
    el.addEventListener('click', (e) => { if (e.target.closest('button, a, input, .img-item')) return; selectCard(card); });
    el.querySelectorAll('.card-head button').forEach((btn) => {
      btn.onclick = () => cardAction(btn.dataset.act, card, idx, el);
    });
    wireCardDrag(el, idx);
    // 图片条：已有图片引用 + 新粘贴图片（统一列表，可拖拽排序）
    if (isEntry) {
      const strip = el.querySelector('[data-strip]');
      renderImages(card, idx, strip);
    }
    return el;
  }

  /** 卡片拖拽排序：仅允许从把手（.drag-handle）发起，避免干扰 textarea 文本选择；
   *  dataTransfer 只认 text/cl-card-idx 类型，与图片条拖拽、文件拖入互不干扰。 */
  function wireCardDrag(el, idx) {
    const handle = el.querySelector('.drag-handle');
    handle.addEventListener('mousedown', () => {
      if (editLocked()) return;
      el.draggable = true;
      // 普通点击把手（未发生拖拽）也必须复位：否则残留的 draggable 会把
      // 卡片内任意子拖拽劫持成卡片移动
      document.addEventListener('mouseup', () => { el.draggable = false; }, { once: true });
    });
    el.addEventListener('dragstart', (e) => {
      // dragstart 会从可拖拽子元素（图片条 item、textarea 文本选区）冒泡上来，
      // 那些拖拽归子元素自己管，卡片层不得取消或改写
      if (e.target !== el) return;
      if (!el.draggable) { e.preventDefault(); return; }
      e.dataTransfer.setData('text/cl-card-idx', String(idx));
      e.dataTransfer.effectAllowed = 'move';
      el.classList.add('dragging');
    });
    el.addEventListener('dragend', () => {
      el.draggable = false;
      el.classList.remove('dragging');
      clearCardDropMarks();
    });
    el.addEventListener('dragover', (e) => {
      if (!e.dataTransfer.types.includes('text/cl-card-idx')) return;
      if (editLocked() || el.classList.contains('dragging')) return;
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
      clearCardDropMarks();
      el.classList.add(cardDropBefore(el, e) ? 'drop-before' : 'drop-after');
    });
    // 拖出卡片（间隙 / add-row）时清掉指示线，不留残影
    el.addEventListener('dragleave', (e) => {
      if (el.contains(e.relatedTarget)) return;
      clearCardDropMarks();
    });
    el.addEventListener('drop', (e) => {
      if (!e.dataTransfer.types.includes('text/cl-card-idx')) return;
      e.preventDefault();
      e.stopPropagation();
      clearCardDropMarks();
      const from = Number(e.dataTransfer.getData('text/cl-card-idx'));
      const targetIdx = Number(el.dataset.idx);
      if (Number.isNaN(from) || Number.isNaN(targetIdx) || from === targetIdx) return;
      let to = cardDropBefore(el, e) ? targetIdx : targetIdx + 1;
      if (from < to) to -= 1; // 先移除再插入的索引补偿
      moveCard(from, to);
    });
  }

  function cardDropBefore(el, e) {
    const rect = el.getBoundingClientRect();
    return e.clientY < rect.top + rect.height / 2;
  }

  function clearCardDropMarks() {
    document.querySelectorAll('.card.drop-before, .card.drop-after')
      .forEach((c) => c.classList.remove('drop-before', 'drop-after'));
  }

  function refreshCardTags(el, card) {
    const changed = card.original != null && card.original !== card.lines.join('\n');
    const tag = el.querySelector('.changed-tag');
    if (changed && !tag) el.querySelector('.card-head').insertAdjacentHTML('beforeend', '<span class="changed-tag">已修改</span>');
    if (!changed && tag) tag.remove();
  }

  function selectCard(card) {
    // 存对象引用而非索引：卡片增删/拖拽重排会让索引整体偏移，索引制会把
    // 粘贴目标指到错误的卡片
    S.selectedCard = card;
    document.querySelectorAll('.card.selected').forEach((c) => c.classList.remove('selected'));
    document.querySelectorAll('#cards .card').forEach((el) => {
      const i = Number(el.dataset.cardId);
      if (S.parsed.get(S.selected)?.cards[i] === card) el.classList.add('selected');
    });
  }

  function fitTextarea(ta) {
    ta.style.height = 'auto';
    ta.style.height = `${Math.max(38, ta.scrollHeight)}px`;
  }

  function cardAction(act, card, idx, el) {
    const parsed = S.parsed.get(S.selected);
    if (act === 'diff') {
      const view = el.querySelector('[data-diff]');
      if (view.style.display === 'none') {
        view.style.display = 'block';
        view.innerHTML = diffHtml(card.original ?? '', card.lines[0] ?? '');
      } else view.style.display = 'none';
      return;
    }
    if (act === 'reset') {
      if (card.original == null) { toast('新条目没有原文可还原', true); return; }
      card.lines[0] = card.original;
      el.querySelector('textarea').value = card.original;
      fitTextarea(el.querySelector('textarea'));
      refreshCardTags(el, card);
      markDirty(); return;
    }
    if (act === 'del') {
      if (!confirm('删除这一条？')) return;
      parsed.cards.splice(idx, 1);
      for (const [id, img] of S.images) {
        if (img.cardKey === `${S.selected}#${idx}`) S.images.delete(id);
      }
      // 删除后后续卡片索引整体前移，按新位置重绑图片归属
      rebindImageCardKeys(parsed, S.selected);
      markDirty(); renderPane(); return;
    }
    if (act === 'img') {
      const input = document.createElement('input');
      input.type = 'file';
      input.accept = 'image/*';
      input.multiple = true;
      input.onchange = async () => {
        for (const file of input.files) await attachImage(card, idx, file);
        renderPane();
      };
      input.click();
    }
  }

  /** 拖拽/重排：移动卡片并按新位置重绑图片归属（cardKey 为索引制）。 */
  function moveCard(from, to) {
    const parsed = S.parsed.get(S.selected);
    if (from === to || from < 0 || to < 0 || from >= parsed.cards.length || to >= parsed.cards.length) return;
    const [moved] = parsed.cards.splice(from, 1);
    parsed.cards.splice(to, 0, moved);
    rebindImageCardKeys(parsed, S.selected);
    S.selectedCard = moved; // 选中跟随被移动的卡片（对象引用）
    markDirty(); renderPane();
  }

  /** 图片元数据的 cardKey 是 `section#idx` 索引制：卡片顺序变化后必须按
   *  当前归属重建，否则删除/恢复/写盘会把图片关联到错误卡片。
   *  sectionName 必须显式传入，避免隐式依赖调用时的 S.selected。 */
  function rebindImageCardKeys(parsed, sectionName) {
    parsed.cards.forEach((card, idx) => {
      for (const im of card.images || []) {
        if (im.kind !== 'new') continue;
        const meta = S.images.get(im.id);
        if (meta) meta.cardKey = `${sectionName}#${idx}`;
      }
    });
  }

  function addCard(kind, atIdx) {
    const parsed = S.parsed.get(S.selected);
    const card = kind === 'heading'
      ? { kind: 'heading', lines: ['### ✨ 提升'], original: null }
      : { kind: 'entry', lines: ['- **新条目标题** ： 具体改动说明。'], images: [], original: null };
    parsed.cards.splice(atIdx, 0, card);
    markDirty();
    renderPane();
    const el = document.querySelector(`.card[data-idx="${atIdx}"] textarea`);
    if (el) { el.focus(); el.select(); }
  }

  function diffHtml(oldText, newText) {
    const ops = L.wordDiff(oldText, newText);
    return ops.map((op) => {
      const text = escapeHtml(op.text);
      if (op.type === 'del') return `<del>${text}</del>`;
      if (op.type === 'ins') return `<ins>${text}</ins>`;
      return text;
    }).join('');
  }

  // ---------- 图片 ----------
  async function toWebp(file) {
    const extOf = (name) => (/\.[a-z0-9]+$/i.exec(name) || ['.png'])[0].toLowerCase();
    try {
      const bitmap = await createImageBitmap(file);
      const maxDim = 1600;
      const scale = Math.min(1, maxDim / Math.max(bitmap.width, bitmap.height));
      const canvas = document.createElement('canvas');
      canvas.width = Math.max(1, Math.round(bitmap.width * scale));
      canvas.height = Math.max(1, Math.round(bitmap.height * scale));
      canvas.getContext('2d').drawImage(bitmap, 0, 0, canvas.width, canvas.height);
      const blob = await new Promise((res) => canvas.toBlob(res, 'image/webp', 0.9));
      bitmap.close?.();
      if (blob && blob.size > 0 && blob.size <= file.size * 1.2) {
        return { blob, filename: `image.webp`, size: blob.size };
      }
      return { blob: file, filename: `image${extOf(file.name)}`, size: file.size };
    } catch {
      return { blob: file, filename: `image${extOf(file.name)}`, size: file.size };
    }
  }

  /** 条目标题 → 文件名基底：去掉文件系统不友好字符，保留中文等 Unicode 字母。 */
  function slugifyTitle(title) {
    return String(title || '')
      .replace(/[\\/:*?"<>|]/g, ' ')
      .replace(/\s+/g, '-')
      .replace(/-{2,}/g, '-')
      .replace(/^[.-]+|[.-]+$/g, '')
      .slice(0, 60)
      .replace(/[.-]+$/g, '');
  }

  async function attachImage(card, idx, file) {
    if (finishInProgress || $('#mask').classList.contains('show')) return;
    const generation = imageOperationGeneration;
    const selected = S.selected;
    const parsed = S.parsed.get(selected);
    const { blob, filename, size } = await toWebp(file);
    const currentIdx = parsed?.cards.indexOf(card) ?? -1;
    if (generation !== imageOperationGeneration || finishInProgress || $('#mask').classList.contains('show')
      || S.selected !== selected || S.parsed.get(selected) !== parsed || currentIdx < 0) {
      toast('图片导入已取消：操作上下文已改变，请在确认结束后重新导入', true);
      return;
    }
    const id = `img-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
    const cardKey = `${selected}#${currentIdx}`;
    const ext = (/(\.[a-z0-9]+)$/i.exec(filename) || ['.webp'])[1];
    const base = slugifyTitle(cardTitleOf(card)) || 'image';
    const siblings = (card.images || [])
      .filter((im) => im.kind === 'new')
      .map((im) => S.images.get(im.id))
      .filter((m) => m && m.base === base).length;
    const defaulted = siblings > 0 ? `${base}-${siblings + 1}${ext}` : `${base}${ext}`;
    S.images.set(id, { id, blob, size, alt: base, filename: defaulted, base, cardKey });
    card.images = card.images || [];
    card.images.push({ kind: 'new', id });
    markDirty();
    toast(`已附加图片到「${truncate(cardTitleOf(card), 18)}」（完成后写入 docs/assets/${S.selected}/）`);
  }

  function cardTitleOf(card) {
    const m = /^-\s*\*\*(.+?)\*\*/.exec(card.lines[0] || '');
    return m ? m[1] : '';
  }

  function truncate(text, n) { return text.length > n ? `${text.slice(0, n)}…` : text; }

  /** 文本输入框内拖动选择文字时，临时关掉 img-item 的 draggable，
   *  否则浏览器会把输入框内的拖动当成整个图片条目的拖拽排序。 */
  function keepTextSelectionOver(item, input) {
    input.addEventListener('mousedown', () => {
      item.draggable = false;
      document.addEventListener('mouseup', () => { item.draggable = true; }, { once: true });
    });
  }

  /** 统一图片条：已有引用与待写盘图片混排，可拖拽排序。 */
  function renderImages(card, idx, strip) {
    strip.innerHTML = '';
    strip.dataset.cardIdx = String(idx);
    (card.images || []).forEach((img, pos) => {
      const item = document.createElement('div');
      item.className = 'img-item';
      item.draggable = true;
      item.dataset.pos = String(pos);
      let thumb = '';
      if (img.kind === 'new') {
        const meta = S.images.get(img.id);
        if (!meta) return;
        const url = URL.createObjectURL(meta.blob);
        const extMatch = /(\.[a-z0-9]+)$/i.exec(meta.filename);
        const ext = extMatch ? extMatch[1] : '';
        const baseName = ext ? meta.filename.slice(0, -ext.length) : meta.filename;
        thumb = `<img src="${url}" alt="" title="点击放大预览">
          <div class="fields">
            <input type="text" data-f="alt" placeholder="alt 描述（默认同文件名）" value="${escapeAttr(meta.alt)}">
            <div style="display:flex; gap:4px; align-items:center;">
              <input type="text" data-f="filename" value="${escapeAttr(baseName)}" title="写入 docs/assets/${escapeAttr(S.selected)}/ 的文件名（不含扩展名）" style="flex:1; min-width:0;">
              <span class="ext-badge">${escapeHtml(ext)}</span>
            </div>
            <div class="meta"><span>${formatSize(meta.size)}</span>
              ${meta.size > 300 * 1024 ? '<span class="big">超过 300 KiB 软上限</span>' : ''}
              <span class="pending">未写盘</span>
              <button data-act="rm">移除</button></div>
          </div>`;
        item.innerHTML = thumb;
        item.querySelectorAll('input[data-f]').forEach((inp) => keepTextSelectionOver(item, inp));
        item.querySelector('img').onclick = () => window.open(url, '_blank');
        item.querySelector('[data-f="alt"]').addEventListener('input', (e) => { meta.alt = e.target.value; markDirty(); });
        item.querySelector('[data-f="filename"]').addEventListener('input', (e) => {
          meta.filename = `${e.target.value.trim()}${ext}`;
          markDirty();
        });
        item.querySelector('[data-act="rm"]').onclick = () => {
          card.images = card.images.filter((x) => x !== img);
          S.images.delete(img.id);
          markDirty(); renderPane();
        };
      } else {
        const absolute = /^https?:\/\//.test(img.path);
        thumb = `<img ${absolute ? `src="${escapeAttr(img.path)}"` : 'data-repo="' + escapeAttr(img.path) + '"'} alt="" title="点击放大预览">
          <div class="fields">
            <input type="text" data-f="alt" value="${escapeAttr(img.alt)}" title="图片 alt 描述">
            <input type="text" data-f="path" value="${escapeAttr(img.path)}" title="图片链接（写回 CL 的路径）">
            <div class="meta"><span>已有</span><button data-act="rm" title="从条目移除该图片行（不删除文件）">移除</button></div>
          </div>`;
        item.innerHTML = thumb;
        item.querySelectorAll('input[data-f]').forEach((inp) => keepTextSelectionOver(item, inp));
        const imgEl = item.querySelector('img');
        if (imgEl.dataset.repo) resolveRepoImage(imgEl, imgEl.dataset.repo);
        else imgEl.onclick = () => window.open(img.path, '_blank');
        item.querySelector('[data-f="alt"]').addEventListener('input', (e) => { img.alt = e.target.value; markDirty(); });
        item.querySelector('[data-f="path"]').addEventListener('input', (e) => { img.path = e.target.value; markDirty(); });
        item.querySelector('[data-act="rm"]').onclick = () => {
          if (!confirm('从条目移除这个图片行？（不会删除磁盘上的图片文件）')) return;
          card.images = card.images.filter((x) => x !== img);
          markDirty(); renderPane();
        };
      }
      item.addEventListener('dragstart', (e) => {
        e.dataTransfer.setData('text/cl-img-pos', String(pos));
        e.dataTransfer.effectAllowed = 'move';
      });
      item.addEventListener('dragover', (e) => {
        if (e.dataTransfer.types.includes('text/cl-img-pos')) { e.preventDefault(); e.dataTransfer.dropEffect = 'move'; }
      });
      item.addEventListener('drop', (e) => {
        if (!e.dataTransfer.types.includes('text/cl-img-pos')) return;
        e.preventDefault();
        e.stopPropagation();
        const from = Number(e.dataTransfer.getData('text/cl-img-pos'));
        const to = Number(item.dataset.pos);
        if (Number.isNaN(from) || from === to) return;
        const [moved] = card.images.splice(from, 1);
        card.images.splice(to, 0, moved);
        markDirty(); renderPane();
      });
      strip.appendChild(item);
    });
    if (!(card.images || []).length) strip.innerHTML = '<span class="hint">Ctrl+V 粘贴截图，或拖入图片文件 / 点卡片 📎 选择。</span>';
  }

  const repoImgCache = new Map();
  async function resolveRepoImage(imgEl, repoPath) {
    // 缓存里有内容（含保存时登记的 blob）直接用；确认读不到（null）才退回链接 chip
    if (repoImgCache.has(repoPath)) {
      const cached = repoImgCache.get(repoPath);
      if (cached) imgEl.src = URL.createObjectURL(cached);
      else imgEl.outerHTML = `<span class="img-ref-chip">🖼 ${escapeHtml(repoPath)}</span>`;
      return;
    }
    if (!S.repo || !repoPath.startsWith('docs/assets/')) {
      // 未连接仓库时只读一次失败即标记，避免闪跳；连接仓库时正常读取
      repoImgCache.set(repoPath, null);
      imgEl.outerHTML = `<span class="img-ref-chip">🖼 ${escapeHtml(repoPath)}</span>`;
      return;
    }
    let blob;
    try {
      const parts = repoPath.split('/');
      const dir = await S.repo.getDirectoryHandle(parts[0]).then((d) => d.getDirectoryHandle(parts[1])).then((d) => d.getDirectoryHandle(parts[2]));
      blob = await (await (await dir.getFileHandle(parts[3])).getFile()).blob();
    } catch { blob = null; }
    repoImgCache.set(repoPath, blob);
    if (blob) imgEl.src = URL.createObjectURL(blob);
    else imgEl.outerHTML = `<span class="img-ref-chip">🖼 ${escapeHtml(repoPath)}</span>`;
  }

  function formatSize(bytes) {
    if (bytes > 1024 * 1024) return `${(bytes / 1024 / 1024).toFixed(1)} MB`;
    return `${Math.max(1, Math.round(bytes / 1024))} KB`;
  }

  // ---------- 粘贴 / 拖放 ----------
  /** 粘贴图片的目标解析。优先级：当前聚焦文本框所在卡片 > 已选中卡片 >
   *  第一条条目（带提示）。目标必须是 entry；heading/文本卡不能带图。 */
  function resolvePasteCard(parsed) {
    const active = document.activeElement;
    const activeEl = active && active.closest ? active.closest('.card') : null;
    if (activeEl) {
      const i = Number(activeEl.dataset.idx);
      const byFocus = Number.isInteger(i) ? parsed.cards[i] : null;
      if (byFocus && byFocus.kind === 'entry') {
        return { card: byFocus, idx: parsed.cards.indexOf(byFocus), source: 'focus' };
      }
    }
    const selected = S.selectedCard;
    if (selected && parsed.cards.includes(selected) && selected.kind === 'entry') {
      return { card: selected, idx: parsed.cards.indexOf(selected), source: 'selected' };
    }
    const first = parsed.cards.find((c) => c.kind === 'entry');
    return first ? { card: first, idx: parsed.cards.indexOf(first), source: 'first' } : null;
  }

  document.addEventListener('paste', async (e) => {
    if (finishInProgress || $('#mask').classList.contains('show')) return;
    if ((S.tab !== 'edit' && S.tab !== 'split') || !S.selected) return;
    const files = [...(e.clipboardData?.items || [])]
      .filter((item) => item.kind === 'file' && item.type.startsWith('image/'))
      .map((item) => item.getAsFile()).filter(Boolean);
    if (!files.length) return;
    const parsed = S.parsed.get(S.selected);
    const target = resolvePasteCard(parsed);
    if (!target) return;
    e.preventDefault();
    if (target.source === 'first') {
      toast(`未选中条目，图片已附加到第一条条目「${truncate(cardTitleOf(target.card), 18)}」`);
    }
    for (const file of files) {
      if (finishInProgress || $('#mask').classList.contains('show')) break;
      await attachImage(target.card, target.idx, file);
    }
    renderPane();
  });

  document.addEventListener('dragover', (e) => {
    if (finishInProgress || $('#mask').classList.contains('show')) return;
    const card = e.target.closest?.('.card');
    if (!card || (S.tab !== 'edit' && S.tab !== 'split')) return;
    // 只拦截携带文件的拖拽；文本选区拖动走浏览器默认行为（不抢选区）
    if (!e.dataTransfer || !Array.from(e.dataTransfer.types || []).includes('Files')) return;
    e.preventDefault();
    card.classList.add('drop-hint');
  });
  document.addEventListener('dragleave', (e) => {
    e.target.closest?.('.card')?.classList.remove('drop-hint');
  });
  document.addEventListener('drop', async (e) => {
    if (finishInProgress || $('#mask').classList.contains('show')) return;
    const cardEl = e.target.closest?.('.card');
    if (!cardEl || (S.tab !== 'edit' && S.tab !== 'split')) return;
    const files = [...e.dataTransfer.files].filter((f) => f.type.startsWith('image/'));
    if (!files.length) return;
    e.preventDefault();
    cardEl.classList.remove('drop-hint');
    const parsed = S.parsed.get(S.selected);
    const idx = Number(cardEl.dataset.idx);
    const card = parsed.cards[idx];
    if (!card || card.kind !== 'entry') { toast('图片只能附加到条目上', true); return; }
    for (const file of files) {
      if (finishInProgress || $('#mask').classList.contains('show')) break;
      await attachImage(card, idx, file);
    }
    renderPane();
  });

  // ---------- 日期 ----------
  $('#vh-date').addEventListener('change', () => {
    const section = S.sections.find((s) => s.name === S.selected);
    if (!section) return;
    const value = $('#vh-date').value;
    section.date = value || null;
    section.heading = value ? `## [${section.name}] - ${value}` : `## [${section.name}]`;
    markDirty();
    renderSidebar();
  });

  // ---------- 选项卡 ----------
  document.querySelectorAll('#tabs button').forEach((btn) => {
    btn.onclick = () => {
      S.tab = btn.dataset.tab;
      document.querySelectorAll('#tabs button').forEach((b) => b.classList.toggle('active', b === btn));
      renderPane();
    };
  });

  // ---------- 预览 ----------
  function escapeHtml(text) {
    return String(text).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  }
  function escapeAttr(text) { return escapeHtml(text); }

  function inlineMd(text, resolveImg) {
    let html = escapeHtml(text);
    html = html.replace(/`([^`]+)`/g, '<code>$1</code>');
    html = html.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
    html = html.replace(/!\[([^\]]*)\]\(([^)\s]+)\)/g, (m, alt, src) => resolveImg(alt, src));
    html = html.replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, '<a href="$2" target="_blank" rel="noreferrer">$1</a>');
    return html;
  }

  function renderPreviewPane(pane) {
    const div = document.createElement('div');
    div.className = 'preview';
    pane.appendChild(div);
    renderPreviewInto(div);
  }

  function renderPreviewInto(container) {
    const parsed = S.parsed.get(S.selected);
    const section = S.sections.find((s) => s.name === S.selected);
    container.innerHTML = '';
    const div = document.createElement('div');
    div.className = 'preview';
    const urlCache = new Map();
    const resolveImg = (alt, src) => {
      if (/^https?:\/\//.test(src)) return `<img src="${escapeAttr(src)}" alt="${escapeAttr(alt)}">`;
      return `<img data-src="${escapeAttr(src)}" alt="${escapeAttr(alt)}">`;
    };
    let html = `<h2>${escapeHtml(section.name)}${section.date ? ` <small style="color:var(--muted)">${section.date}</small>` : ''}</h2>`;
    let inList = false;
    for (const card of parsed.cards) {
      const line = card.lines[0] || '';
      if (card.kind === 'heading') {
        if (inList) { html += '</ul>'; inList = false; }
        html += `<h3>${inlineMd(line.replace(/^#+\s*/, ''), resolveImg)}</h3>`;
        continue;
      }
      if (card.kind === 'entry') {
        if (!inList) { html += '<ul>'; inList = true; }
        html += `<li>${inlineMd(line.replace(/^-\s*/, ''), resolveImg)}`;
        for (const img of card.images || []) {
          if (img.kind === 'existing') html += resolveImg(img.alt, img.path);
          else {
            const meta = S.images.get(img.id);
            if (meta) html += `<img src="${URL.createObjectURL(meta.blob)}" alt="${escapeAttr(meta.alt)}">`;
          }
        }
        html += '</li>';
        continue;
      }
      if (inList) { html += '</ul>'; inList = false; }
      html += `<p>${inlineMd(line, resolveImg)}</p>`;
    }
    if (inList) html += '</ul>';
    div.innerHTML = html;
    container.appendChild(div);
    // 用仓库句柄解析已有图片
    div.querySelectorAll('img[data-src]').forEach(async (img) => {
      const src = img.dataset.src;
      if (S.repo && src.startsWith('docs/assets/')) {
        let blob = urlCache.get(src);
        if (blob === undefined) {
          try {
            const parts = src.split('/');
            const dir = await S.repo.getDirectoryHandle(parts[0]).then((d) => d.getDirectoryHandle(parts[1])).then((d) => d.getDirectoryHandle(parts[2]));
            const fh = await dir.getFileHandle(parts[3]);
            blob = await (await fh.getFile()).blob();
          } catch { blob = null; }
          urlCache.set(src, blob);
        }
        if (blob) { img.src = URL.createObjectURL(blob); return; }
      }
      img.outerHTML = `<span class="img-missing">[图片：${escapeHtml(src)}]</span>`;
    });
  }

  // ---------- 对照 ----------
  /** 正式版的对照来源：文档顺序中它与上一个正式版之间的全部测试版小节。 */
  function referenceSources(version) {
    const idx = S.sections.findIndex((s) => s.name === version);
    const sources = [];
    for (let i = idx + 1; i < S.sections.length; i += 1) {
      const s = S.sections[i];
      if (L.isStable(s.name)) break;
      if (s.name !== '未发布') sources.push(s);
    }
    return sources;
  }

  function renderReferencePane(pane) {
    const section = S.sections.find((s) => s.name === S.selected);
    const sources = L.isStable(section.name) ? referenceSources(section.name) : [];
    const wrap = document.createElement('div');
    wrap.className = 'preview';
    if (!sources.length) {
      wrap.innerHTML = '<p class="hint">此版本没有可对照的测试版小节（对照覆盖上一正式版之后的全部测试版）。</p>';
      pane.appendChild(wrap);
      return;
    }
    wrap.innerHTML = `<p class="hint">逐条勾选已核对过的测试版条目（按版本保存）。确认合并稿覆盖了全部内容后即可「完成编辑」。</p>`;
    const checked = new Set(JSON.parse(localStorage.getItem(LS_REFS()) || '[]'));
    for (const src of sources) {
      const parsed = S.parsed.get(src.name);
      const group = document.createElement('div');
      group.className = 'ref-group';
      group.innerHTML = `<h4>${escapeHtml(src.name)} <span class="hint">(${src.date || ''})</span></h4>`;
      parsed.cards.forEach((card, i) => {
        if (card.kind !== 'entry') return;
        const key = `${src.name}#${i}`;
        const row = document.createElement('label');
        row.className = 'ref-entry' + (checked.has(key) ? ' done' : '');
        row.innerHTML = `<input type="checkbox" ${checked.has(key) ? 'checked' : ''}><span class="text">${inlineMd(card.lines[0].replace(/^-\s*/, ''), (a, s) => `<span class="img-missing">[图]</span>`)}</span>`;
        row.querySelector('input').addEventListener('change', (e) => {
          if (e.target.checked) checked.add(key); else checked.delete(key);
          row.classList.toggle('done', e.target.checked);
          localStorage.setItem(LS_REFS(), JSON.stringify([...checked]));
        });
        group.appendChild(row);
      });
      wrap.appendChild(group);
    }
    pane.appendChild(wrap);
  }

  // ---------- 序列化 ----------
  function serializeCurrentDoc() {
    const { preamble, sections } = L.splitSections(S.clText);
    const parts = [preamble];
    for (const section of sections) {
      const parsed = S.parsed.get(section.name);
      parts.push(parsed ? L.serializeSection(section, parsed) : section.rawText);
    }
    return parts.join('');
  }

  function isDirty() {
    if (serializeCurrentDoc() !== S.baseText) return true;
    return S.images.size > 0;
  }

  // ---------- 自动保存 ----------
  let autosaveTimer = null;
  function scheduleAutosave() {
    clearTimeout(autosaveTimer);
    autosaveTimer = setTimeout(saveSession, 900);
  }
  function saveSession() {
    if (!S.baseHash) return;
    const refs = [];
    for (const [id, img] of S.images) {
      refs.push({ id, alt: img.alt, filename: img.filename, size: img.size, cardKey: img.cardKey });
    }
    const status = $('#save-status');
    try {
      localStorage.setItem(LS_STATE(), JSON.stringify({
        savedAt: Date.now(),
        docText: serializeCurrentDoc(),
        selected: S.selected,
        imageCount: S.images.size,
      }));
      localStorage.setItem(LS_IMGS(), JSON.stringify(refs));
      idbPutAll(refs);
      status.className = '';
      status.textContent = `已自动保存 ${new Date().toLocaleTimeString()}`;
      return true;
    } catch (e) {
      console.warn('autosave failed', e);
      if (!status.classList.contains('fail')) {
        toast('自动保存失败（可能是浏览器存储配额已满）：请尽快「完成编辑」把图片写盘，避免丢失', true);
      }
      status.className = 'fail';
      status.textContent = '自动保存失败';
      return false;
    }
  }

  // ---------- IndexedDB（图片二进制） ----------
  function idbOpen() {
    return new Promise((resolve, reject) => {
      const req = indexedDB.open('cl-editor', 2);
      req.onupgradeneeded = () => {
        const db = req.result;
        if (!db.objectStoreNames.contains('images')) db.createObjectStore('images');
        if (!db.objectStoreNames.contains('handles')) db.createObjectStore('handles');
      };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error);
    });
  }
  // 目录句柄持久化：FileSystemDirectoryHandle 可结构化克隆入 IDB（FSA 标准做法），
  // 下次启动用它免掉手动选目录；权限过期时浏览器只会弹一次授权确认。
  async function idbSaveHandle(handle) {
    const db = await idbOpen();
    const tx = db.transaction('handles', 'readwrite');
    tx.objectStore('handles').put(handle, 'repo-root');
    await new Promise((res) => { tx.oncomplete = res; tx.onerror = res; });
    db.close();
  }
  async function idbLoadHandle() {
    const db = await idbOpen();
    const tx = db.transaction('handles', 'readonly');
    const req = tx.objectStore('handles').get('repo-root');
    const out = await new Promise((res) => { req.onsuccess = () => res(req.result ?? null); req.onerror = () => res(null); });
    db.close();
    return out ?? null;
  }
  async function idbClearHandle() {
    const db = await idbOpen();
    const tx = db.transaction('handles', 'readwrite');
    tx.objectStore('handles').delete('repo-root');
    await new Promise((res) => { tx.oncomplete = res; tx.onerror = res; });
    db.close();
  }
  async function idbPutAll(refs) {
    if (!S.images.size) return;
    const db = await idbOpen();
    const tx = db.transaction('images', 'readwrite');
    const store = tx.objectStore('images');
    for (const [id, img] of S.images) store.put(img.blob, id);
    await new Promise((res) => { tx.oncomplete = res; tx.onerror = res; });
    db.close();
  }
  async function idbGetAll(ids) {
    const db = await idbOpen();
    const tx = db.transaction('images', 'readonly');
    const store = tx.objectStore('images');
    const out = new Map();
    await Promise.all(ids.map((id) => new Promise((res) => {
      const req = store.get(id);
      req.onsuccess = () => { out.set(id, req.result); res(); };
      req.onerror = () => res();
    })));
    db.close();
    return out;
  }

  async function doRestore(state) {
    S.clText = state.docText;
    reparse();
    const ids = [];
    // 依据持久化的 refs 找回新图片元数据（blobs 在 IDB）
    const refList = JSON.parse(localStorage.getItem(LS_IMGS()) || '[]');
    for (const ref of refList) {
      const [sectionName, idxStr] = ref.cardKey.split('#');
      const parsed = S.parsed.get(sectionName);
      if (!parsed) continue;
      const card = parsed.cards[Number(idxStr)];
      if (!card || card.kind !== 'entry') continue;
      card.images = card.images || [];
      card.images.push({ kind: 'new', id: ref.id });
      S.images.set(ref.id, { ...ref });
      ids.push(ref.id);
    }
    const blobs = await idbGetAll(ids);
    for (const [id, blob] of blobs) if (blob && S.images.get(id)) S.images.get(id).blob = blob;
    $('#restore-banner').style.display = 'none';
    selectSection(state.selected);
    markDirty();
    toast('已恢复上次编辑（图片写入前请勿清除浏览器数据，blob 由本页 IndexedDB 保存）');
  }

  // ---------- 写盘辅助 ----------
  async function dirHandle(pathParts, create) {
    let dir = S.repo;
    for (const part of pathParts) dir = await dir.getDirectoryHandle(part, { create: Boolean(create) });
    return dir;
  }
  async function writeFileAt(pathParts, blob) {
    const dir = await dirHandle(pathParts.slice(0, -1), true);
    const fh = await dir.getFileHandle(pathParts.at(-1), { create: true });
    const writable = await fh.createWritable();
    await writable.write(blob);
    await writable.close();
  }
  async function readFileAt(pathParts) {
    try {
      const dir = await dirHandle(pathParts.slice(0, -1), false);
      const fh = await dir.getFileHandle(pathParts.at(-1));
      return await (await fh.getFile()).text();
    } catch { return null; }
  }
  async function backupFile(pathParts, backupDir) {
    const content = await readFileAt(pathParts);
    if (content == null) return null;
    const target = [...backupDir, ...pathParts];
    await writeFileAt(target, new Blob([content], { type: 'text/markdown' }));
    return target.join('/');
  }

  // ---------- 归档状态 ----------
  async function refreshArchiveStatus() {
    for (const section of S.sections) {
      if (!L.isStable(section.name)) continue;
      try {
        const expected = await L.buildArchive(S.clText, section.name);
        const existing = S.repo ? await readFileAt(['docs', 'releases', `${section.name}.md`]) : null;
        S.archiveStatus.set(section.name, existing == null ? 'missing' : (existing === expected ? 'fresh' : 'stale'));
      } catch {
        S.archiveStatus.set(section.name, 'none');
      }
    }
  }

  // ---------- 完成编辑（支持多版本批量） ----------
  function newImagesOf(versionName) {
    const parsed = S.parsed.get(versionName);
    const out = [];
    for (const card of parsed.cards) {
      if (card.kind !== 'entry') continue;
      for (const imgRef of card.images || []) {
        if (imgRef.kind === 'new') out.push({ card, imgRef, meta: S.images.get(imgRef.id) });
      }
    }
    return out;
  }

  function collectErrors(versionName) {
    const parsed = S.parsed.get(versionName);
    const section = S.sections.find((s) => s.name === versionName);
    const errors = [];
    if (section.name !== '未发布' && L.isStable(section.name) && !section.date) {
      errors.push('正式版需要设置日期（标题行 `## [版本] - YYYY-MM-DD`）');
    }
    if (section.name === '未发布' && newImagesOf(versionName).length) {
      errors.push('「未发布」区不支持配图（没有对应的 docs/assets 版本目录）');
    }
    const names = new Map();
    for (const { meta } of newImagesOf(versionName)) {
      const name = meta.filename.trim();
      const valid = /^[^\\/:*?"<>|\s][^\\/:*?"<>|]*\.(?:webp|png|jpe?g|gif|avif|svg)$/i.test(name)
        && !name.includes('..') && name.length <= 100;
      if (!valid) {
        errors.push(`文件名不合法：${name}（不能包含 \\ / : * ? " < > | 或空格，需以图片扩展名结尾）`);
      }
      if (names.has(name)) errors.push(`文件名重复：${name}`);
      names.set(name, meta.id);
    }
    for (let i = parsed.cards.length - 1; i >= 0; i -= 1) {
      const card = parsed.cards[i];
      if (card.kind === 'entry' && card.original == null && (card.lines[0] || '').trim() === '- **新条目标题** ： 具体改动说明。') {
        errors.push(`第 ${i + 1} 张卡片仍是新条目模板，请填写或删除`);
        break;
      }
    }
    return errors;
  }

  function validateForFinish(versionName = S.selected) {
    return collectErrors(versionName);
  }

  /** 有改动（文本或新图片）的版本。 */
  function dirtyVersions() {
    const out = [];
    for (const section of S.sections) {
      const parsed = S.parsed.get(section.name);
      if (!parsed) continue;
      const textChanged = L.serializeSection(section, parsed) !== section.rawText;
      const hasNew = parsed.cards.some((c) => (c.images || []).some((im) => im.kind === 'new'));
      if (textChanged || hasNew) out.push(section);
    }
    return out;
  }

  async function finishEditing() {
    if (finishInProgress) return;
    const dirty = dirtyVersions();
    if (!dirty.length) { toast('没有需要完成的修改', true); return; }
    const allErrors = [];
    for (const section of dirty) {
      allErrors.push(...collectErrors(section.name).map((e) => `[${section.name}] ${e}`));
    }
    if (allErrors.length) {
      modal(`<h3>还不能完成编辑</h3>${allErrors.map((e) => `<p class="step">⚠ ${escapeHtml(e)}</p>`).join('')}
        <div style="margin-top:14px;text-align:right"><button data-close-modal>知道了</button></div>`);
      return;
    }
    if (dirty.length === 1) {
      const section = dirty[0];
      const archive = section.name !== '未发布' && L.isStable(section.name) && $('#auto-archive').checked;
      await applyFinish([section.name], new Set(archive ? [section.name] : []));
      return;
    }
    renderBatchModal(dirty);
  }

  function renderBatchModal(dirty) {
    const rows = dirty.map((section) => {
      const imgCount = newImagesOf(section.name).length;
      const stable = L.isStable(section.name);
      return `<div class="step">
        <input type="checkbox" data-batch="${escapeAttr(section.name)}" checked>
        <span><strong>${escapeHtml(section.name)}</strong>
        ${section.name === '未发布' ? '<span class="badge unrel">仅文本</span>' : ''}
        ${imgCount ? `，${imgCount} 张新图片` : '，仅文本修改'}</span>
        ${stable ? `<label class="hint" style="margin-left:auto"><input type="checkbox" data-batch-arch="${escapeAttr(section.name)}" checked>重生成归档</label>` : ''}
      </div>`;
    }).join('');
    modal(`<h3>完成编辑 — ${dirty.length} 个版本有改动</h3>
      ${rows}
      <p class="hint" style="margin:12px 0 0">写入顺序：备份 → 各版本图片 → 一次性写回 CHANGELOG.md → 重生成勾选的归档。</p>
      <div style="margin-top:16px;text-align:right">
        <button data-close-modal>取消</button>
        <button id="btn-batch-go" class="primary">开始写入</button>
      </div>`);
    $('#btn-batch-go').onclick = () => {
      const versions = [...document.querySelectorAll('[data-batch]')].filter((b) => b.checked).map((b) => b.dataset.batch);
      if (!versions.length) { toast('未勾选任何版本', true); return; }
      const archives = new Set([...document.querySelectorAll('[data-batch-arch]')]
        .filter((b) => b.checked && versions.includes(b.dataset.batchArch)).map((b) => b.dataset.batchArch));
      closeModal();
      applyFinish(versions, archives);
    };
  }

  async function blobSha256(blob) {
    const digest = await crypto.subtle.digest('SHA-256', new Uint8Array(await blob.arrayBuffer()));
    return Array.from(new Uint8Array(digest), (b) => b.toString(16).padStart(2, '0')).join('');
  }

  /** 冲突处置：磁盘 CL 与载入基线不一致时，让用户选择覆盖 / 另存 / 取消。 */
  function resolveConflictModal() {
    return new Promise((resolve) => {
      modal(`<h3>⚠ CHANGELOG.md 在磁盘上已被修改</h3>
        <p class="hint">页面载入后，磁盘内容发生了变化（可能是 git 操作或外部编辑）。无论怎么选，磁盘当前版本都会先备份到 <code>.artifacts/changelog-editor/backup/</code>。</p>
        <div style="display:flex; gap:10px; justify-content:flex-end; margin-top:16px">
          <button id="cf-cancel">取消</button>
          <button id="cf-side">另存为单独文件</button>
          <button id="cf-force" class="primary">强行覆盖</button>
        </div>`, () => resolve('cancel'));
      $('#cf-cancel').onclick = () => { closeModal(); resolve('cancel'); };
      $('#cf-side').onclick = () => { closeModal(); resolve('sidefile'); };
      $('#cf-force').onclick = () => { closeModal(); resolve('force'); };
    });
  }

  async function uniqueManualSavePath() {
    const dir = ['.artifacts', 'changelog-editor', 'manual-save'];
    for (let i = 0; i < 100; i += 1) {
      const stamp = new Date().toISOString().replace(/[-:T]/g, '').slice(0, 14);
      const name = i ? `CHANGELOG-${stamp}-${i}.md` : `CHANGELOG-${stamp}.md`;
      if (await readFileAt([...dir, name]) == null) return [...dir, name];
    }
    return [...dir, `CHANGELOG-${Date.now()}.md`];
  }

  async function applyFinish(versionNames, archiveSet) {
    if (finishInProgress) return;
    finishInProgress = true;
    imageOperationGeneration += 1;
    refreshBackgroundLock();
    const steps = [];
    const log = (text) => { steps.push(text); };
    const written = [];
    const processedIds = [];
    let sideFile = false;
    try {
      if (S.repo) {
        // 1) 冲突检查：覆盖 / 另存 / 取消
        const onDisk = await readFileAt(['CHANGELOG.md']);
        if (onDisk !== S.baseText) {
          const action = await resolveConflictModal();
          if (action === 'cancel') { toast('已取消：未写入任何文件'); return; }
          const stamp = new Date().toISOString().replace(/[-:T]/g, '').slice(0, 14);
          const backupDir = ['.artifacts', 'changelog-editor', 'backup', stamp];
          await backupFile(['CHANGELOG.md'], backupDir);
          for (const name of archiveSet) await backupFile(['docs', 'releases', `${name}.md`], backupDir);
          log(`磁盘版本已先备份 → ${backupDir.join('/')}/`);
          sideFile = action === 'sidefile';
        } else {
          const stamp = new Date().toISOString().replace(/[-:T]/g, '').slice(0, 14);
          const backupDir = ['.artifacts', 'changelog-editor', 'backup', stamp];
          await backupFile(['CHANGELOG.md'], backupDir);
          for (const name of archiveSet) await backupFile(['docs', 'releases', `${name}.md`], backupDir);
          log(`已备份原文件 → ${backupDir.join('/')}/`);
        }
        // 2) 各版本写图片，并把新图片转为已有引用（保持条目内的顺序）
        for (const name of versionNames) {
          const dedupe = new Map();
          let count = 0;
          for (const { card, imgRef, meta } of newImagesOf(name)) {
            if (!meta) continue;
            const filename = meta.filename.trim();
            const key = await blobSha256(meta.blob);
            if (dedupe.has(key)) meta.finalName = dedupe.get(key);
            else {
              dedupe.set(key, filename);
              await writeFileAt(['docs', 'assets', name, filename], meta.blob);
              meta.finalName = filename;
            }
            imgRef.kind = 'existing';
            imgRef.alt = (meta.alt || cardTitleOf(card) || name).trim();
            imgRef.path = `docs/assets/${name}/${meta.finalName}`;
            delete imgRef.id;
            repoImgCache.set(imgRef.path, meta.blob); // 缩略图直接复用内存 blob
            written.push(`docs/assets/${name}/${meta.finalName}（${formatSize(meta.size)}）`);
            processedIds.push(meta.id);
            count += 1;
          }
          if (count) log(`${name}：写入 ${count} 张图片 → docs/assets/${name}/`);
        }
        // 3) 写回 CL（冲突时可选另存为单独文件，不动磁盘 CL 与归档）
        const newDoc = serializeCurrentDoc();
        if (sideFile) {
          const target = await uniqueManualSavePath();
          await writeFileAt(target, new Blob([newDoc], { type: 'text/markdown' }));
          S.clText = newDoc;
          log(`已另存为 ${target.join('/')}（git 忽略目录；磁盘 CHANGELOG.md 与归档未动，请手动合并后重新载入）`);
        } else {
          await writeFileAt(['CHANGELOG.md'], new Blob([newDoc], { type: 'text/markdown' }));
          S.clText = newDoc; S.baseText = newDoc;
          log('已写回 CHANGELOG.md（图片链接已插入到对应条目后）');
          // 4) 归档
          for (const name of archiveSet) {
            const archive = await L.buildArchive(S.clText, name);
            await writeFileAt(['docs', 'releases', `${name}.md`], new Blob([archive], { type: 'text/markdown' }));
            log(`已生成归档 docs/releases/${name}.md（与 prepare_release_notes.py 同契约）`);
          }
          await refreshArchiveStatus();
        }
      } else {
        // 降级：下载
        for (const name of versionNames) {
          for (const { card, imgRef, meta } of newImagesOf(name)) {
            if (!meta) continue;
            meta.finalName = meta.filename.trim();
            imgRef.kind = 'existing';
            imgRef.alt = meta.alt || cardTitleOf(card) || name;
            imgRef.path = `docs/assets/${name}/${meta.finalName}`;
            delete imgRef.id;
            triggerDownload(meta.blob, meta.finalName);
            written.push(`docs/assets/${name}/${meta.finalName}`);
            processedIds.push(meta.id);
          }
        }
        const newDoc = serializeCurrentDoc();
        triggerDownload(new Blob([newDoc], { type: 'text/markdown' }), 'CHANGELOG.md');
        for (const name of archiveSet) {
          triggerDownload(new Blob([await L.buildArchive(newDoc, name)], { type: 'text/markdown' }), `${name}.md`);
        }
        log('只读模式：已通过下载交付 CHANGELOG / 归档 / 图片，请手动放回对应位置');
        S.clText = serializeCurrentDoc(); S.baseText = S.clText;
      }
      for (const id of processedIds) S.images.delete(id);
      reparseFromText(S.clText);
      if (sideFile) {
        // 另存模式：磁盘 CL 未更新，保持未保存状态与自动保存，方便之后手动合并
        markDirty();
        renderSidebar();
      } else {
        markClean();
        localStorage.removeItem(LS_STATE());
        localStorage.removeItem(LS_IMGS());
        renderSidebar();
      }
      const selected = S.selected;
      selectSection(S.sections.some((s) => s.name === selected) ? selected : S.sections[0].name);
      const tags = [...archiveSet].map((name) => `v${name}`);
      modal(`
        <h3>${sideFile ? '📄 完成编辑（已另存，待手动合并）' : '✅ 完成编辑'} — ${escapeHtml(versionNames.join('、'))}</h3>
        ${steps.map((s) => `<div class="step"><span class="s">✓</span><span>${escapeHtml(s)}</span></div>`).join('')}
        ${written.length ? `<p class="hint" style="margin:10px 0 4px">写入的文件：</p><div class="paths">${written.map(escapeHtml).join('<br>')}</div>` : ''}
        ${sideFile
          ? '<p class="hint" style="margin:12px 0 4px">手动合并另存文件后，回到本页点击「打开仓库目录」重新载入即可继续。</p>'
          : `<p class="hint" style="margin:12px 0 4px">建议接着在仓库根目录执行：</p>
        <code>uv run --no-sync python scripts/prepare_release_notes.py --check-all</code>
        ${tags.map((tag) => `<br><code>uv run --no-sync python scripts/prepare_release_notes.py --tag ${escapeHtml(tag)} --output .artifacts/release-preview.md</code>`).join('')}`}
        <div style="margin-top:16px;text-align:right"><button class="primary" data-close-modal>好</button></div>`);
    } catch (error) {
      modal(`<h3>⚠ 完成编辑中断</h3><p>${escapeHtml(error.message)}</p>
        <p class="hint">已执行的步骤不会回滚；被覆盖的文件在最近一次备份目录里。</p>
        <div style="text-align:right"><button data-close-modal>知道了</button></div>`);
    } finally {
      finishInProgress = false;
      refreshBackgroundLock();
    }
  }

  function reparseFromText(text) {
    S.clText = text;
    reparse();
  }

  function triggerDownload(blob, filename) {
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = filename;
    a.click();
  }

  $('#btn-finish').onclick = finishEditing;

  // ---------- 批量归档 ----------
  $('#btn-select-stale').onclick = () => {
    document.querySelectorAll('[data-arch]').forEach((box) => {
      box.checked = S.archiveStatus.get(box.dataset.arch) !== 'fresh';
    });
  };
  $('#btn-generate-archives').onclick = async () => {
    if (!S.repo) { toast('只读模式下不支持写归档', true); return; }
    const targets = [...document.querySelectorAll('[data-arch]')]
      .filter((box) => box.checked).map((box) => box.dataset.arch);
    if (!targets.length) { toast('先勾选要生成的正式版', true); return; }
    // 归档必须与 CL 文件一致：先把当前编辑保存回盘
    const docText = serializeCurrentDoc();
    if (docText !== S.baseText || (await readFileAt(['CHANGELOG.md'])) !== S.baseText) {
      if ((await readFileAt(['CHANGELOG.md'])) !== S.baseText) {
        const action = await resolveConflictModal();
        if (action !== 'force') { toast('已取消：未写入任何文件'); return; }
      }
      const stamp = new Date().toISOString().replace(/[-:T]/g, '').slice(0, 14);
      await backupFile(['CHANGELOG.md'], ['.artifacts', 'changelog-editor', 'backup', stamp]);
      await writeFileAt(['CHANGELOG.md'], new Blob([docText], { type: 'text/markdown' }));
      S.baseText = docText;
      toast('已先把当前编辑保存到 CHANGELOG.md');
    }
    const results = [];
    for (const name of targets) {
      try {
        const archive = await L.buildArchive(S.clText, name);
        const existing = await readFileAt(['docs', 'releases', `${name}.md`]);
        if (existing != null && existing !== archive) {
          const stamp = new Date().toISOString().replace(/[-:T]/g, '').slice(0, 14);
          await backupFile(['docs', 'releases', `${name}.md`], ['.artifacts', 'changelog-editor', 'backup', stamp]);
        }
        await writeFileAt(['docs', 'releases', `${name}.md`], new Blob([archive], { type: 'text/markdown' }));
        results.push(`✓ ${name}.md${existing == null ? '（新建）' : ''}`);
      } catch (error) {
        results.push(`✗ ${name}.md：${error.message}`);
      }
    }
    await refreshArchiveStatus();
    renderSidebar();
    modal(`<h3>归档生成结果</h3>${results.map((r) => `<div class="step"><span class="s">${r.startsWith('✓') ? '✓' : '✗'}</span><span>${escapeHtml(r.slice(2))}</span></div>`).join('')}
      <div style="margin-top:14px;text-align:right"><button class="primary" data-close-modal>好</button></div>`);
  };

  // ---------- 载入入口 ----------
  $('#btn-open').onclick = openRepo;
  $('#btn-load-file').onclick = loadFileFallback;

  // 手动编辑：请 dev-dashboard server 用系统默认编辑器打开仓库根的 CHANGELOG.md。
  // 仅当页面经 dev-dashboard 访问（同源提供 /api/open-changelog）时可用。
  $('#btn-external-edit').onclick = async () => {
    try {
      const res = await fetch('/api/open-changelog', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: '{}',
      });
      const data = await res.json().catch(() => null);
      if (res.ok && data?.ok) toast('已调起系统编辑器打开 CHANGELOG.md');
      else toast(data?.error ?? '调起失败：该功能需通过 dev-dashboard（node tools/dev-dashboard/serve.mjs）访问', true);
    } catch {
      toast('调起失败：该功能需通过 dev-dashboard（node tools/dev-dashboard/serve.mjs）访问', true);
    }
  };

  // 刷新：丢弃页面修改，从磁盘重新载入（外部编辑器改完之后用）
  $('#btn-reload-cl').onclick = async () => {
    if (!S.repo) { toast('未连接仓库目录，无法从磁盘刷新', true); return; }
    if (isDirty() && !confirm('页面有未保存的修改，从磁盘重新载入将丢弃这些修改。继续？')) return;
    // 既然确认了丢弃，就同步清掉本轮会话的存档与待写图片，避免：
    // 1) 同 hash 时 loadClText 又把刚丢弃的存档当「未完成编辑」复活；
    // 2) 失去挂靠的 S.images 残留导致脏态永真、幽灵 refs 持续自动保存。
    localStorage.removeItem(LS_STATE());
    localStorage.removeItem(LS_REFS());
    localStorage.removeItem(LS_IMGS());
    S.images.clear();
    const text = await readFileAt(['CHANGELOG.md']);
    if (text == null) { toast('读取 CHANGELOG.md 失败', true); return; }
    await loadClText(text, S.repoName);
    await refreshArchiveStatus();
    renderSidebar();
    toast('已从磁盘重新载入 CHANGELOG.md');
  };
  $('#btn-reconnect').onclick = async () => {
    const handle = await idbLoadHandle();
    if (!handle) { hideReconnectUi(); return; }
    if (!(await tryReconnect(handle))) {
      toast('未能重连：请在浏览器弹窗中允许访问，或重新手动选择目录', true);
    }
  };
  $('#btn-forget-repo').onclick = async () => {
    await idbClearHandle().catch(() => {});
    hideReconnectUi();
    toast('已忘记记住的仓库目录');
  };
  bootReconnect();

  // 侧栏拖宽（记忆宽度）
  const savedSidebarWidth = localStorage.getItem('cl-editor:sidebar-w');
  if (savedSidebarWidth) $('#sidebar').style.width = savedSidebarWidth;

  // 侧栏收缩/展开（记忆状态）
  const SIDEBAR_COLLAPSED_KEY = 'cl-editor:sidebar-collapsed';
  function applySidebarCollapsed(collapsed) {
    $('#sidebar').classList.toggle('collapsed', collapsed);
    document.body.classList.toggle('side-collapsed', collapsed);
    const btn = $('#sidebar-toggle');
    btn.textContent = collapsed ? '⟩' : '⟨';
    btn.title = collapsed ? '展开侧栏（版本列表与归档生成）' : '收起侧栏（版本列表与归档生成）';
  }
  $('#sidebar-toggle').addEventListener('click', () => {
    const collapsed = !$('#sidebar').classList.contains('collapsed');
    applySidebarCollapsed(collapsed);
    localStorage.setItem(SIDEBAR_COLLAPSED_KEY, collapsed ? '1' : '');
  });
  applySidebarCollapsed(localStorage.getItem(SIDEBAR_COLLAPSED_KEY) === '1');

  $('#sb-resizer').addEventListener('mousedown', (e) => {
    e.preventDefault();
    const sidebar = $('#sidebar');
    const startX = e.clientX;
    const startWidth = sidebar.getBoundingClientRect().width;
    const onMove = (ev) => {
      const width = Math.min(560, Math.max(200, startWidth + ev.clientX - startX));
      sidebar.style.width = `${width}px`;
    };
    const onUp = () => {
      document.removeEventListener('mousemove', onMove);
      document.removeEventListener('mouseup', onUp);
      document.body.classList.remove('resizing');
      localStorage.setItem('cl-editor:sidebar-w', sidebar.style.width);
    };
    document.body.classList.add('resizing');
    document.addEventListener('mousemove', onMove);
    document.addEventListener('mouseup', onUp);
  });

  $('#modal').addEventListener('click', event => {
    if (event.target.closest('[data-close-modal]')) closeModal(true);
  });

  window.addEventListener('beforeunload', (e) => {
    if (isDirty()) { e.preventDefault(); e.returnValue = ''; }
  });
}
  mountChangelogEditor(createChangelogLibrary());
})();
